{"code": "import pandas as pd
from collections import Counter

# Read the XLS file
df = pd.read_excel('/tmp/extracted_zip/food_duplicates.xls', engine='xlrd')

# Get all food items including column headers
all_foods = []
for col in df.columns:
    all_foods.append(col.strip().lower())  # column header
    for val in df[col]:
        if pd.notna(val):
            all_foods.append(val.strip().lower())

print(f"Total food items (including headers): {len(all_foods)}")
print(f"Unique food items: {len(set(all_foods))}")

# Count occurrences
counts = Counter(all_foods)
print(f"\nFoods appearing exactly once:")
for food, count in counts.items():
    if count == 1:
        print(f"  '{food}'")

print(f"\nFoods appearing more than once:")
for food, count in counts.items():
    if count > 1:
        print(f"  '{food}': {count}")"}

